import React, { useState, useEffect } from 'react';

const ProductReviews = ({ productId, showTitle = true }) => {
  const [reviews, setReviews] = useState([]);

  useEffect(() => {
    const fetchReviews = () => {
      const allReviews = JSON.parse(localStorage.getItem('productReviews')) || [];
      // Match reviews by product ID or title matching
      const matched = allReviews.filter(
        (r) => String(r.productId) === String(productId)
      );
      setReviews(matched);
    };

    fetchReviews();

    // Listen to storage events so new reviews pop up in real-time
    window.addEventListener('storage', fetchReviews);
    return () => window.removeEventListener('storage', fetchReviews);
  }, [productId]);

  // Calculate average rating score
  const avgRating = reviews.length > 0
    ? (reviews.reduce((acc, r) => acc + Number(r.rating || 0), 0) / reviews.length).toFixed(1)
    : null;

  return (
    <div style={{ marginTop: '14px', paddingTop: '12px', borderTop: '1px solid #e2e8f0' }}>
      
      {/* Header & Rating Summary */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '10px' }}>
        {showTitle && (
          <h5 style={{ margin: 0, fontSize: '14px', fontWeight: '700', color: '#0f172a' }}>
            Customer Reviews ({reviews.length})
          </h5>
        )}
        {avgRating && (
          <span style={{
            backgroundColor: '#fef3c7',
            color: '#92400e',
            padding: '2px 8px',
            borderRadius: '12px',
            fontSize: '12px',
            fontWeight: 'bold'
          }}>
            ★ {avgRating} / 5.0
          </span>
        )}
      </div>

      {/* Reviews List */}
      {reviews.length === 0 ? (
        <p style={{ margin: 0, fontSize: '12px', color: '#94a3b8', fontStyle: 'italic' }}>
          No reviews submitted yet for this product.
        </p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', maxHeight: '180px', overflowY: 'auto' }}>
          {reviews.map((rev, idx) => (
            <div key={idx} style={{ backgroundColor: '#f8fafc', padding: '10px 12px', borderRadius: '8px', border: '1px solid #f1f5f9' }}>
              
              {/* Star Rating & Title */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '2px' }}>
                <span style={{ color: '#f59e0b', fontSize: '13px', fontWeight: 'bold' }}>
                  {'★'.repeat(rev.rating)}{'☆'.repeat(5 - rev.rating)}
                </span>
                {rev.title && (
                  <strong style={{ fontSize: '13px', color: '#0f172a' }}>{rev.title}</strong>
                )}
              </div>

              {/* Description */}
              <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#334155', lineHeight: '1.4' }}>
                "{rev.description}"
              </p>

              {/* Date Footer */}
              <span style={{ fontSize: '10px', color: '#94a3b8', display: 'block', marginTop: '4px' }}>
                {rev.date || 'Verified Buyer'}
              </span>

            </div>
          ))}
        </div>
      )}

    </div>
  );
};

export default ProductReviews;
